"""Package the full-size A1 Mini iteration and its verification artifacts."""
from pathlib import Path
from PIL import Image
import json, html, zipfile
R=Path(__file__).resolve().parents[1];O=R/'output/a1_full_size'
b=json.loads((O/'BOM.json').read_text());v=json.loads((O/'print_checks.json').read_text())
assert b['printed_piece_count']==740 and b['unique_printed_parts']==19
assert v['complete_slice_coverage'] and len(v['slices'])==21
imgs=sorted((O/'renders').glob('*.png'));assert len(imgs)==10
pages=[Image.open(p).convert('RGB') for p in imgs];pages[0].save(O/'A1_Full_Size_Visual_Guide.pdf',save_all=True,append_images=pages[1:],resolution=150)
for p in pages:p.close()
rows=''.join('<tr><td>'+html.escape(a['code'])+'</td><td>'+str(a['quantity'])+'</td><td>'+' × '.join(f'{n:g}' for n in a['print_bounds_mm'])+'</td><td><a href="printable/'+a['file']+'">STL</a></td></tr>' for a in b['parts'])
figs=''.join(f'<figure><a href="renders/{p.name}"><img loading="lazy" src="renders/{p.name}" alt="{p.stem}"></a></figure>' for p in imgs)
(O/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A1 Mini full-size racing gate</title><style>body{font:17px/1.6 system-ui;max-width:1150px;margin:40px auto;padding:0 24px;color:#183044;background:#edf1f3}h1{line-height:1.15}a{color:#075b92}nav{display:flex;gap:24px;flex-wrap:wrap}figure{margin:24px 0}img{width:100%;border-radius:8px}.card{background:white;border-radius:8px;padding:20px;margin:20px 0}table{border-collapse:collapse;width:100%;background:white}td,th{padding:8px 12px;text-align:left;border-bottom:1px solid #ddd}</style><h1>Full-size gate. Every printed part fits.</h1><p>Twelve whole 22 × 28 inch sheets; four rigid 2152 × 565 mm borders; one PVC backing frame with four diagonal braces. 2716.4 mm outside, 1586.8 mm nominal opening.</p><nav><a href="Assembly_and_Test_Instructions.pdf">Assembly &amp; test manual (16 pages)</a><a href="A1_Full_Size_Gate.blend">Blender model</a><a href="A1_Full_Size_Visual_Guide.pdf">Ten-page visual PDF</a><a href="BUILD_AND_PRINT_GUIDE.md">Build and print guide</a><a href="BOM.csv">Complete printed BOM</a><a href="print_checks.json">Verification</a></nav><div class="card"><h2>Build-volume result</h2><p><strong>19 unique types / 740 printed pieces.</strong> The longest piece is 144.2 mm. Every unique part fits the A1 Mini without diagonal placement and slices successfully with supports off. Rear ribs now use overlapping short sections; the center cross has two levels. Only two universal channel types remain: 120 long and 96 short. Both use common symmetric mounting features and registered splints with ties. Eight gate-corner keys and sixteen PVC dock keys use the same reversible printed fork bridge.</p><p>This is a digital fabrication prototype. Physical fit, snap cycling, assembled rigidity and wind performance remain untested. Workshop joints use ties and stay assembled during transport.</p></div><div class="card"><h2>Start with nine pieces</h2><p><a href="sliced/Minimal_Concept_Test_9_Parts/Minimal_Concept_Test_9_Parts_A1Mini_PETG.3mf">Minimal concept test plate</a> · <a href="MINIMAL_CONCEPT_TEST.md">Parts and test steps</a></p><p><strong>32.4 g PETG / about 95 minutes.</strong> Tests paper fit, a straight splice, a frame corner, and a complete snap-on PVC dock. One of each part; reuse the channels between tests.</p><h2>Earlier interface sampler</h2><p><a href="sliced/Fit_Kit_1to1_LAYOUT/Fit_Kit_1to1_LAYOUT_A1Mini_PETG.3mf">Sliced 1:1 PETG fit kit for A1 Mini</a> · <a href="printable/Fit_Kit_1to1_LAYOUT.3mf">Geometry-only layout</a></p><p>Twelve actual parts on one plate: about <strong>38.5 g / 113 minutes</strong>. A1 Mini, 0.4 mm nozzle, 0.20 mm layers, three walls, 15% infill, Generic PETG, Textured PEI Plate, no supports. Check the settings in Bambu Studio before printing. No job has been sent to a printer.</p></div><div class="card"><h2>Material and workshop tradeoff</h2><p><strong>2.97 kg PETG; 3.26 kg with reserve → four 1 kg spools.</strong> Plastic plus paper is about $71.23 consumed at the stated $20/kg and $0.99/sheet assumptions, excluding ties, PVC, bases and labor. Four complete spools plus paper cost $91.88 at those assumptions.</p><p>The kit also uses <strong>856 ties</strong>. Model-only print estimates sum to roughly 146 hours before batching effects. Whole-sheet yield saves cutting but brings considerable printing and assembly work. The former 1.84 kg schematic estimate is superseded.</p></div><h2>Every printed part</h2><table><thead><tr><th>File / part</th><th>Per gate</th><th>Print X × Y × Z, mm</th><th>Download</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>Purchased fasteners, pipe cutting assumptions, base details and rail variant placement are in the build guide. The view labels refer to exact exported geometry; most purchased ties are omitted for clarity.</p>'''+figs+'''<p>Rebuild source and validation scripts are in the repository's scripts directory. This iteration keeps the earlier anchored grass / ballasted hard-floor base arrangement; fitting bodies and bases are omitted in these component views.</p></html>''')
with zipfile.ZipFile(O/'A1_Full_Size_Kit.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for p in sorted(O.rglob('*')):
  if p.is_file() and p.suffix not in ['.zip','.blend1','.log','.gcode'] and p.name!='.DS_Store' and not (p.parent.name=='manual_assets' and p.suffix=='.png'):z.write(p,Path('output/a1_full_size')/p.relative_to(O))
 for name in ['build_a1_full_size.py','slice_a1_full_size.py','validate_a1_full_size.py','package_a1_full_size.py','build_minimal_concept_test.py','build_assembly_manual.py','export_assembly_manual_meshes.py','validate_assembly_manual.py','build_gate.py','face_geometry.py']:z.write(R/'scripts'/name,Path('scripts')/name)
 for name in ['BUILD_GUIDE.md','PVC_CUT_LIST.csv','HARD_SURFACE_ADD_ON.csv']:z.write(R/'output'/name,Path('output')/name)
 z.writestr('README.txt','Start at output/a1_full_size/index.html.\nPrint the full-size interface fit kit before production.\nThe earlier 1:15 tabletop model is a separate repository artifact and is not bundled here.\n')
print('Packaged 19 full-size part files, 21 verified slices, 10 visual scenes and assembly documentation.')
